#include <string>
#include <vector>

class Solution {
public:
    long long countSubstrings(std::string s) {
        std::vector<std::vector<long long>> dp(10);
        for (int m = 1; m <= 9; ++m) dp[m].assign(m, 0);

        long long total = 0;
        for (char ch : s) {
            int x = ch - '0';
            std::vector<std::vector<long long>> next_dp(10);
            for (int m = 1; m <= 9; ++m) next_dp[m].assign(m, 0);

            for (int m = 1; m <= 9; ++m) {
                next_dp[m][x % m] += 1;
                for (int r = 0; r < m; ++r) {
                    if (dp[m][r] > 0) {
                        int new_r = (r * 10 + x) % m;
                        next_dp[m][new_r] += dp[m][r];
                    }
                }
            }
            if (x > 0) {
                total += next_dp[x][0];
            }
            dp = next_dp;
        }
        return total;
    }
};

class Solution {
    public long countSubstrings(String s) {
        long[][] dp = new long[10][];
        for (int m = 1; m <= 9; m++) dp[m] = new long[m];

        long total = 0;
        for (char ch : s.toCharArray()) {
            int x = ch - '0';
            long[][] nextDp = new long[10][];
            for (int m = 1; m <= 9; m++) nextDp[m] = new long[m];

            for (int m = 1; m <= 9; m++) {
                nextDp[m][x % m] += 1;
                for (int r = 0; r < m; r++) {
                    if (dp[m][r] > 0) {
                        int newR = (r * 10 + x) % m;
                        nextDp[m][newR] += dp[m][r];
                    }
                }
            }
            if (x > 0) {
                total += nextDp[x][0];
            }
            dp = nextDp;
        }
        return total;
    }
}

var countSubstrings = function(s) {
    let dp = Array.from({ length: 10 }, (_, m) => new BigInt64Array(m));
    let total = 0n;

    for (let i = 0; i < s.length; i++) {
        const x = s.charCodeAt(i) - 48;
        const nextDp = Array.from({ length: 10 }, (_, m) => new BigInt64Array(m));

        for (let m = 1; m <= 9; m++) {
            nextDp[m][x % m] += 1n;
            for (let r = 0; r < m; r++) {
                if (dp[m][r] > 0n) {
                    const newR = (r * 10 + x) % m;
                    nextDp[m][newR] += dp[m][r];
                }
            }
        }
        if (x > 0) {
            total += nextDp[x][0];
        }
        dp = nextDp;
    }
    return Number(total);
};
